#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <string.h>
#include <dlfcn.h>
#include <stdlib.h>
#include <math.h>

/*
 * Fast leading-eigenvector solver for a real sparse CSR matrix.
 * Drives ARNAUD (the ARPACK-compatible reverse communication solver shipped
 * inside scipy) directly, performing the matrix-vector products in C, which
 * removes the Python callback overhead of scipy.sparse.linalg.eigs.
 *
 * Calling conventions recovered from the scipy _arpacklib wrapper:
 *   ARNAUD_dnaupd(state, resid, v, n, ipntr, workd, workl)
 *   ARNAUD_dneupd(state, rvec, howmny, select, dr, di, z, sigmar, sigmai,
 *                 workev, resid, v, n, ldv, ipntr, workd, workl)
 * state is the 0xc0-byte struct packed by pack_dict_to_state_d.
 */

typedef void (*dnaupd_fn)(void*, double*, double*, long, int*, double*, double*);
typedef void (*dneupd_fn)(void*, int, int, int*, double*, double*, double*,
                          double, double, double*, double*, double*, long, long,
                          int*, double*, double*);

static dnaupd_fn dnaupd = NULL;
static dneupd_fn dneupd = NULL;

static int load(void) {
    if (dnaupd) return 0;
    void* h = dlopen("/Users/mark/Desktop/AI/Pivotal/.venv/lib/python3.11/site-packages/scipy/sparse/linalg/_eigen/arpack/_arpacklib.cpython-311-darwin.so", RTLD_NOW | RTLD_GLOBAL);
    if (!h) return -1;
    dnaupd = (dnaupd_fn)dlsym(h, "ARNAUD_dnaupd");
    dneupd = (dneupd_fn)dlsym(h, "ARNAUD_dneupd");
    return (dnaupd && dneupd) ? 0 : -1;
}

#define PI(st, off, v) do { int _v=(v); memcpy((char*)(st)+(off), &_v, 4);} while(0)
#define GI(st, off) (*((int*)((char*)(st)+(off))))

static PyObject* leading(PyObject* self, PyObject* args) {
    PyObject *indptr_o, *indices_o, *data_o;
    int k, ncv, maxiter;
    double tol;
    if (!PyArg_ParseTuple(args, "OOOiiid", &indptr_o, &indices_o, &data_o, &k, &ncv, &maxiter, &tol))
        return NULL;
    if (load()) { PyErr_SetString(PyExc_RuntimeError, "cannot load ARNAUD"); return NULL; }

    Py_buffer indptr_b, indices_b, data_b;
    if (PyObject_GetBuffer(indptr_o, &indptr_b, PyBUF_SIMPLE) < 0) return NULL;
