    PyObject *ret = NULL;
    if (info == 0 && nconv > 0) {
        PI(st, 0x38, 0);
        int *select = calloc(ncv, 4);
        int kout = k + 1;
        double *dr = calloc(kout, 8), *di = calloc(kout, 8);
